// Shared TinyMCE configuration for every page.
//
// React-free on purpose: hosts pass plain options plus a couple of callbacks.
// Track changes is opt-in via the `trackChanges` flag (see trackChangesOptions).
import { applyTrackChangesOptions } from './trackChangesOptions.js';

// TinyMCE is loaded as a runtime <script> from the self-hosted copy in
// public/tinymce/ (generated by postinstall.js), not bundled as a module.
export const TINYMCE_SRC = '/tinymce/tinymce.min.js';

// Every free Community plugin in the self-hosted package. Track changes is a
// core `setup`, not a plugin, so this list is identical with or without it.
export const PLUGINS = Object.freeze([
  'accordion', 'advlist', 'anchor', 'autolink', 'autosave', 'charmap', 'code',
  'codesample', 'directionality', 'emoticons', 'fullscreen', 'image', 'importcss',
  'insertdatetime', 'link', 'lists', 'media', 'nonbreaking', 'pagebreak',
  'preview', 'quickbars', 'save', 'searchreplace', 'table', 'visualblocks',
  'visualchars', 'wordcount',
]);

// One entry per toolbar group, so callers can append/remove a single group.
// Joined with ' | ' when the init object is built.
export const TOOLBAR_GROUPS = Object.freeze([
  'undo redo',
  'bold italic underline strikethrough',
  'blocks fontfamily',
  'fontsize lineheight',
  'alignleft aligncenter alignright alignjustify',
  'bullist numlist',
  'forecolor backcolor removeformat',
  'outdent indent',
  'ltr rtl',
  'link unlink anchor',
  'image media table',
  'charmap emoticons pagebreak hr',
  'accordion codesample',
  'searchreplace visualblocks visualchars code',
  'save fullscreen preview',
]);

// In-browser image upload so the Upload tab works without a backend.
export const imagesUploadHandler = (blobInfo) =>
  new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = () => reject('Upload failed');
    reader.readAsDataURL(blobInfo.blob());
  });

// Options shared by every page. Page-specific bits (height, placeholder, …)
// come in through `overrides` or as separate props. `toolbar`, `plugins` and the
// track-changes keys are added by `createEditorInit`.
export const BASE_INIT = {
  // Sizing
  height: 500,
  resize: true,

  // Bar / toolbar
  menubar: 'file edit view insert format tools table help',
  toolbar_mode: 'wrap',
  contextmenu: 'link image table',

  // Responsive overrides (applied after the top-level options).
  mobile: {
    menubar: 'file edit view insert format tools table help',
    toolbar_mode: 'sliding',
  },

  // Status bar
  statusbar: true,
  elementpath: true,
  promotion: false,
  branding: false,
  placeholder: 'Write your blog post…',

  // Image uploads — this is what makes the Upload tab appear.
  automatic_uploads: true,
  image_uploadtab: true,
  image_advtab: true,
  image_title: true,
  image_caption: true,
  images_file_types: 'jpeg,jpg,png,gif,webp,svg',
  images_reuse_filename: true,
  images_upload_handler: imagesUploadHandler,

  // Links
  link_default_target: '_blank',
  link_assume_external_targets: true,
  link_context_toolbar: true,

  // Media
  media_live_embeds: true,

  // Paste
  paste_data_images: true,
  smart_paste: true,

  // Formatting
  block_formats:
    'Paragraph=p;Heading 1=h1;Heading 2=h2;Heading 3=h3;Heading 4=h4;Preformatted=pre;Blockquote=blockquote',
  font_family_formats:
    'System UI=system-ui,sans-serif;Georgia=Georgia,serif;Times=Times New Roman,serif;Courier=Courier New,monospace;Arial=Arial,sans-serif',
  font_size_formats: '12px 14px 16px 18px 24px 36px',
  line_height_formats: '1 1.2 1.5 2',
  style_formats: [
    { title: 'Lead paragraph', block: 'p', classes: 'lead' },
    { title: 'Callout', block: 'div', classes: 'callout' },
    { title: 'Inline code', inline: 'code' },
  ],
  color_map: [
    '#000000', 'Black', '#ffffff', 'White', '#ef4444', 'Red',
    '#2563eb', 'Blue', '#16a34a', 'Green', '#f59e0b', 'Amber',
  ],

  // Code samples
  codesample_languages: [
    { text: 'HTML/XML', value: 'markup' },
    { text: 'JavaScript', value: 'javascript' },
    { text: 'CSS', value: 'css' },
    { text: 'JSON', value: 'json' },
    { text: 'Python', value: 'python' },
  ],

  // Autosave (draft kept in the browser)
  autosave_interval: '30s',

  // Quickbars
  quickbars_selection_toolbar: 'bold italic | link h2 h3 blockquote',
  quickbars_insert_toolbar: 'image quicktable',

  // Pull page classes into the Formats menu
  importcss_append: true,

  // Tables
  table_sizing_mode: 'responsive',
  table_toolbar:
    'tableprops tabledelete | tableinsertrowbefore tableinsertrowafter tabledeleterow | tableinsertcolbefore tableinsertcolafter tabledeletecol',

  // Misc
  indent: true,
  forced_root_block: 'p',
  newline_behavior: 'block',
  directionality: 'ltr',
  content_language: 'en',
  a11y_advanced_options: true,
  xss_sanitization: true,
  deprecation_warnings: true,
  noneditable_class: 'mceNonEditable',

  // Attribute allow-list. Track changes overrides this with its own set.
  extended_valid_elements: 'p[*],span[*],delete[*],insert[*]',

  // Store absolute URLs so the saved HTML works on any host.
  relative_urls: false,
  remove_script_host: false,
};

// Build a fresh init object. `trackChanges` is the only switch.
export function createEditorInit({
  trackChanges = false,
  author,
  enabled = true,
  onStateChange,
  onSetup,
  setup,
  overrides,
} = {}) {
  const init = {
    ...BASE_INIT,
    plugins: [...PLUGINS],
    toolbar: TOOLBAR_GROUPS.join(' | '),
    ...overrides,
  };

  if (trackChanges) {
    return applyTrackChangesOptions(init, {
      author,
      enabled,
      onStateChange,
      onSetup,
      setup,
    });
  }

  return setup ? { ...init, setup } : init;
}

// Everything <Editor> needs, minus the page's own initialValue.
export function createEditorConfig(options) {
  return {
    tinymceScriptSrc: TINYMCE_SRC,
    licenseKey: 'gpl',
    init: createEditorInit(options),
  };
}
